const KB = {"facts": [{"topic": "what_is_mooziac", "fact": "Mooziac is an ultra-lightweight, 100% native macOS music player written in pure Swift and AppKit with zero external Swift Package Manager dependencies."}, {"topic": "what_is_mooziac", "fact": "Mooziac is designed as a lightweight, distraction-free alternative to Electron and Chromium wrappers like Spotify and YouTube Music Desktop, living in the macOS menu bar."}, {"topic": "license_and_copyright", "fact": "Mooziac is free and open-source software licensed under the MIT License, Copyright (c) 2026 ThreeTen."}, {"topic": "trademark_disclaimer", "fact": "YouTube Music is a trademark of Google LLC. Mooziac is an independent open-source project and is not affiliated with, sponsored, or endorsed by Google LLC."}, {"topic": "macos_compatibility", "fact": "Mooziac requires macOS 13.0 (Ventura) or later, running on both Apple Silicon (M1/M2/M3/M4/M5) and Intel (x86_64) Macs."}, {"topic": "universal_binary", "fact": "Mooziac ships as a Universal 2 macOS application containing both arm64 and x86_64 slices compiled and merged via lipo."}, {"topic": "bundle_identifier", "fact": "Mooziac's official macOS application bundle identifier is app.mooziac.mac."}, {"topic": "zero_third_party_runtime_deps", "fact": "Mooziac relies exclusively on Apple system frameworks (AppKit, WebKit, AVFoundation, CoreAudio, MediaPlayer, UserNotifications, Carbon, QuartzCore) with no third-party libraries."}, {"topic": "installation_homebrew", "fact": "Mooziac can be installed via Homebrew by running 'brew install shirkeharsh/tap/mooziac'."}, {"topic": "updating_homebrew", "fact": "Mooziac installed via Homebrew can be upgraded by running 'brew upgrade --cask mooziac'."}, {"topic": "installation_direct_download", "fact": "Mooziac is distributed directly via GitHub Releases as 'Mooziac.dmg' and 'Mooziac.zip'."}, {"topic": "gatekeeper_macos", "fact": "Because Mooziac is distributed directly outside the Mac App Store and not notarized with an Apple Developer ID ticket, macOS Gatekeeper may display a prompt stating the developer cannot be verified."}, {"topic": "gatekeeper_open_anyway", "fact": "To bypass the Gatekeeper warning, users can navigate to System Settings > Privacy & Security and click 'Open Anyway' under the Security section."}, {"topic": "gatekeeper_xattr_command", "fact": "Users can clear the macOS quarantine attribute on Mooziac by executing 'xattr -cr /Applications/Mooziac.app' in Terminal."}, {"topic": "first_launch_experience", "fact": "Upon launch, Mooziac mounts an NSStatusItem in the macOS menu bar, shows a pop-in icon animation, and initializes docked directly beneath the status button."}, {"topic": "updating_in_app", "fact": "Mooziac features a built-in UpdateManager that checks the GitHub Releases API (https://api.github.com/repos/shirkeharsh/mooziac/releases/latest) for new versions."}, {"topic": "updating_check_interval", "fact": "Automatic background update checks are throttled to once every 24 hours (86,400 seconds) using UserDefaults key 'Mooziac_lastUpdateCheckTimestamp'."}, {"topic": "updating_manual_check", "fact": "Users can trigger a manual update check at any time by right-clicking the Mooziac menu bar icon and selecting 'Check for Updates...' or pressing the 'u' key while the menu is active."}, {"topic": "uninstalling_basic", "fact": "To uninstall Mooziac, quit the application completely and drag '/Applications/Mooziac.app' to the macOS Trash."}, {"topic": "uninstalling_complete_cleanup", "fact": "To perform a complete removal of all local data, users can delete '~/Library/Application Support/Mooziac/', '~/Library/Caches/Mooziac/', '~/Library/Preferences/app.mooziac.mac.plist', and optionally their local music directory '~/Music/Mooziac/'."}, {"topic": "ytm_integration", "fact": "Mooziac streams YouTube Music inside an isolated WKWebView instance configured with custom CSS, ad-skipping scripts, and native DOM bridges."}, {"topic": "ytm_account_support", "fact": "Mooziac works seamlessly with both free YouTube Music accounts and YouTube Music Premium accounts without requiring a paid subscription."}, {"topic": "ytm_streaming_bitrate", "fact": "Mooziac forces high-bitrate audio stream selection in YouTube Music, requesting 256 kbps AAC or 160 kbps Opus formats."}, {"topic": "ytm_login", "fact": "Users sign in to YouTube Music directly inside the app's browser view (360x650 px); credentials and cookies are stored securely in Apple's native WKWebsiteDataStore."}, {"topic": "ytm_reset_login", "fact": "Users can clear their login session and cookies by right-clicking the menu bar icon and selecting 'Reset Login (Fresh Start)', which wipes WKWebsiteDataStore records and reloads the homepage."}, {"topic": "ytm_innertube_client", "fact": "Mooziac uses a lightweight Swift client for YouTube Music's internal InnerTube API at https://music.youtube.com/youtubei/v1 using public web client key AIzaSyAO_FJ2SlqU8Q4STEHLGCilw_Y9_11qcW8."}, {"topic": "ytm_sapisid_auth", "fact": "When signed in, YTMClient generates an authenticated SAPISIDHASH header from the SAPISID or __Secure-1PAPISID cookies stored in WKWebsiteDataStore."}, {"topic": "ytm_audio_keepalive", "fact": "To prevent macOS from freezing the WebContent process during track switches, Mooziac injects a silent zero-gain Web Audio AudioContext node that keeps audio output active during transitions."}, {"topic": "ytm_ad_skipping", "fact": "Mooziac's DOM observer automatically detects ad playing states, triggers ad skip buttons (.ytp-ad-skip-button, etc.), and suppresses ad metadata from appearing on Now Playing cards or Discord RPC."}, {"topic": "dual_audio_engine", "fact": "Mooziac incorporates a dual audio engine: an online WebKit streaming engine and a native AVFoundation lossless audio engine (NativeAudioPlayer)."}, {"topic": "local_audio_formats", "fact": "Mooziac's local audio engine supports MP3, M4A, AAC, WAV, FLAC, ALAC, AIFF, AIF, OGG, and OPUS audio file formats."}, {"topic": "local_audio_flac", "fact": "Mooziac natively decodes and plays FLAC lossless audio files locally without transcoding or external third-party decoders."}, {"topic": "local_audio_metadata", "fact": "When scanning local audio files, Mooziac extracts track title, artist, album name, duration, and embedded cover artwork using AVURLAsset common metadata."}, {"topic": "local_audio_importing", "fact": "Users can import audio files into Mooziac via Context Menu > 'Import Audio Files to Location...', which copies selected files into the configured music folder."}, {"topic": "download_pipeline", "fact": "Mooziac contains an integrated offline download manager that uses yt-dlp to download, convert audio, and embed metadata and artwork."}, {"topic": "download_stages", "fact": "Mooziac's download pipeline reports granular progress across three distinct stages: network downloading, audio conversion, and metadata/lyrics tag finalization."}, {"topic": "download_helper_yt_dlp", "fact": "Mooziac automatically fetches and configures the standalone universal macOS yt-dlp binary into '~/Library/Application Support/Mooziac/bin/yt-dlp' with 0755 permissions."}, {"topic": "download_locations_default", "fact": "By default, Mooziac stores all downloaded tracks in '~/Music/Mooziac/'."}, {"topic": "download_locations_custom", "fact": "Users can configure a custom download folder by right-clicking the menu bar icon -> Settings -> 'Select Download Location...', stored in UserDefaults key 'YTM_downloadsFolder'."}, {"topic": "download_queue_persistence", "fact": "Active and queued downloads are persisted in SQLite across app launches so pending downloads resume smoothly upon restart."}, {"topic": "download_failures_handling", "fact": "If yt-dlp fails due to timeout or missing binary, DownloadManager attempts a native URLSession fallback download before marking the task as failed."}, {"topic": "playlists_tabs", "fact": "Mooziac's library interface is divided into 4 tabs: Playlists, Liked Songs, Downloads, and History."}, {"topic": "playlists_import_from_url", "fact": "Users can import public or unlisted YouTube Music / YouTube playlists by pasting a playlist URL in Menu -> Settings -> 'Import Playlist from Link...' (shortcut 'i')."}, {"topic": "liked_songs_sync", "fact": "When signed in to YouTube Music, liking a track in Mooziac (via heart button, keyboard shortcut 'L', or global shortcut) synchronizes directly to the user's YouTube Music account via InnerTube."}, {"topic": "liked_songs_offline", "fact": "Liked songs are stored locally in the SQLite database 'liked_songs' table, enabling offline tracking even when not connected to YouTube Music."}, {"topic": "listening_history_storage", "fact": "Mooziac tracks played songs in a local SQLite table 'listening_history', recording song title, artist, album, artwork URL, source type (online or local), and timestamp."}, {"topic": "listening_history_clear", "fact": "Users can clear their entire listening history by selecting 'Clear Listening History' from the status bar context menu, which displays a warning confirmation dialog."}, {"topic": "trackpad_multitouch_api", "fact": "Mooziac captures trackpad events directly by dynamically loading macOS PrivateFramework '/System/Library/PrivateFrameworks/MultitouchSupport.framework/MultitouchSupport' via dlopen."}, {"topic": "trackpad_permissions", "fact": "Mooziac does not require macOS Accessibility permissions to process trackpad gestures because it uses low-level Multitouch contact frame callbacks directly."}, {"topic": "trackpad_volume_zone", "fact": "The trackpad edge volume slider is triggered exclusively along the top 30% of the rightmost edge of the trackpad (distance from right <= 2.5mm or normalized x >= 0.982, and normalized y >= 0.70)."}, {"topic": "trackpad_volume_threshold", "fact": "To eliminate accidental touches while typing, the edge volume gesture requires at least 3.0mm of vertical finger travel before volume adjustments engage, then re-anchors to prevent jumps."}, {"topic": "trackpad_volume_scaling", "fact": "The volume slider uses a smooth 160.0mm travel distance for a full 0% to 100% volume transition, clamped to a maximum change of 0.25 per frame."}, {"topic": "trackpad_haptics", "fact": "Mooziac plays macOS mechanical navigation click sounds (AudioServicesPlaySystemSound 1104) and Taptic Engine feedback during gesture triggers."}, {"topic": "trackpad_bottom_right_corner", "fact": "Double-tapping the bottom-right corner of the trackpad (y <= 0.15) skips to the Next Track, while triple-tapping skips to the Previous Track by default."}, {"topic": "trackpad_bottom_left_corner", "fact": "Double-tapping the bottom-left corner of the trackpad (x <= 0.005 or dist <= 2.5mm, y <= 0.15) toggles Play/Pause, while triple-tapping toggles the Centered Lyrics HUD by default."}, {"topic": "trackpad_gesture_remapping", "fact": "All 4 corner tap triggers (Bottom-Right 2 Taps, Bottom-Right 3 Taps, Bottom-Left 2 Taps, Bottom-Left 3 Taps) can be remapped in settings to 16 distinct actions including seeking, volume, mute, shuffle, and repeat."}, {"topic": "trackpad_gesture_tutorial", "fact": "Mooziac includes an interactive visual gesture tutorial window (press 't' in Context Menu or open via Settings) rendered in a borderless dark overlay."}, {"topic": "volume_modes", "fact": "Mooziac supports two volume control modes: System Sound (adjusts the Mac's master CoreAudio output device) and Focus Audio / Separate App Sound (adjusts only Mooziac's media volume)."}, {"topic": "loudness_leveling", "fact": "Mooziac includes Loudness Leveling (target -14 LUFS) that normalizes playback volume across songs using track loudnessDb metadata with a 250ms smooth cosine easing curve to prevent sudden volume surges."}, {"topic": "volume_scroll_menu_bar", "fact": "Scrolling over the Mooziac menu bar icon adjusts volume: 6 points of trackpad scrolling adjusts volume by 2%, while a discrete mouse wheel notch adjusts volume by 4%."}, {"topic": "auto_pause_on_headphone_disconnect", "fact": "When headphones or AirPods disconnect, Mooziac's AudioRouteMonitor detects the default CoreAudio output change and automatically pauses playback if 'isAutoPauseOnDisconnectEnabled' is active."}, {"topic": "keyboard_shortcuts_local", "fact": "When Mooziac has focus: Spacebar toggles Play/Pause, Left Arrow rewinds 4s (8s on key repeat), Right Arrow advances 4s (8s on key repeat), Up Arrow increases volume by 5%, Down Arrow decreases volume by 5%, and 'L' toggles like status."}, {"topic": "keyboard_seeking_modifiers", "fact": "Holding Option with Left/Right Arrow jumps 15 seconds, while holding Shift with Left/Right Arrow jumps 30 seconds."}, {"topic": "keyboard_shortcuts_global", "fact": "Mooziac registers global macOS hotkeys via native Carbon event handlers for Control+Option (or Cmd+Shift) with Space (Play/Pause), Right Arrow (Next Track), Left Arrow (Previous Track), and 'L' (Like Track)."}, {"topic": "keyboard_smart_advance", "fact": "Seeking within 1.5 seconds of a track's end automatically advances to the next track in the playlist or queue."}, {"topic": "keyboard_text_field_suppression", "fact": "Mooziac suppresses Spacebar and arrow key playback hotkeys when typing into search fields, comments, or web input fields inside WKWebView."}, {"topic": "lyrics_hud_window", "fact": "Mooziac displays real-time line-by-line synchronized lyrics in a floating, non-intrusive HUD window (CenteredMenuBarLyricsWindowController) centered beneath the macOS menu bar and notch area."}, {"topic": "lyrics_fallback_tiers", "fact": "Mooziac fetches lyrics across 5 prioritized tiers: Tier 0 (Local .lrc sidecars and ~/Music/Mooziac), Tier 0.5 (Local cache ~/Library/Caches/Mooziac/Lyrics), Tier 0.8 (Official YouTube Music InnerTube synced lyrics), Tier 1 (LRCLib exact match), Tier 2 (LRCLib title+artist search), Tier 3 (LRCLib title search), and Tier 4 (Plain text / Lyrics.ovh spaced every 4s)."}, {"topic": "lyrics_caching_validation", "fact": "Cached LRC files are verified against the active track title using [ti:...] tags and Jaccard token similarity; corrupted or mismatched lyric files are automatically evicted."}, {"topic": "lyrics_polling_rate", "fact": "When the lyrics HUD is visible, WebKit and playback observers poll at 4 Hz (every 250ms) to ensure lyric lines synchronize smoothly with zero visual drift."}, {"topic": "lyrics_next_track_prefetching", "fact": "Mooziac automatically prefetches synced lyrics and track loudness for the next song in the queue before the current song finishes."}, {"topic": "lyrics_hud_overlay_messages", "fact": "The CenteredMenuBarLyricsWindowController also acts as an on-screen display (OSD) overlay for volume adjustments, track change notifications, muting, and mode switches."}, {"topic": "discord_rpc_socket", "fact": "Mooziac connects to Discord desktop clients via direct native Unix domain IPC sockets (/tmp/discord-ipc-0 through 9) with zero external Node.js, Python, or Discord SDK dependencies."}, {"topic": "discord_rpc_client_id", "fact": "Mooziac's registered Discord application client ID is 1537169013174435870."}, {"topic": "discord_rpc_data_transmitted", "fact": "Discord Rich Presence broadcasts only current song title, artist, album/playlist name, album artwork URL, and start/end playback timestamps; no private account info or history is transmitted."}, {"topic": "discord_rpc_auto_reconnect", "fact": "DiscordRPCManager listens for NSWorkspace.didLaunchApplicationNotification to automatically detect when Discord opens and re-establish the IPC handshake."}, {"topic": "player_form_factors", "fact": "Mooziac provides multiple UI form factors: a compact 360x120 pill docked under the menu bar, a detachable floating Dynamic Island player, and an expanded 360x650 browse view."}, {"topic": "player_themes", "fact": "Mooziac offers 4 distinct aesthetic themes: Adaptive (Ambient Dark), OLED Dark Mode, Pure Crystal Glass Mode, and Watery Pure Transparent (Liquid Fluid)."}, {"topic": "adaptive_theme", "fact": "In Adaptive (Ambient Dark) mode, Mooziac samples primary and secondary colors in real-time from active album artwork and projects an ambient glowing backdrop."}, {"topic": "oled_theme", "fact": "OLED Dark Mode renders a pure pitch-black (#000000) container with crisp high-contrast white typography, designed for OLED and mini-LED MacBook screens."}, {"topic": "crystal_glass_theme", "fact": "Pure Crystal Glass Mode features a translucent frosted glass card with a reinforced 1.2px solid #B3B8B5 perimeter border for high visibility on light wallpapers."}, {"topic": "liquid_fluid_theme", "fact": "Watery Pure Transparent (Liquid Fluid) theme dynamically adapts to macOS system appearance: frosted glass with dark charcoal typography in Light Mode, and obsidian liquid glass with white typography in Dark Mode."}, {"topic": "progress_styles", "fact": "Mooziac includes 4 selectable timeline track progress styles: Waveform (dynamic 32-bar reactive waves), Neon Glow (glowing liquid capsule), Cyber Dots (pulsing LED matrix), and Minimal Line (precision audio line)."}, {"topic": "floating_player_detachment", "fact": "Users can drag the Dynamic Island player away from the menu bar to float anywhere on screen; dragging changes window level from .statusBar to .floating and reveals a 'Dock Back' reset button."}, {"topic": "multidisplay_handling", "fact": "When external displays are connected, disconnected, or reconfigured, DisplayManager automatically clamps floating and docked windows to visible screen bounds with safe margins."}, {"topic": "privacy_zero_telemetry", "fact": "Mooziac features a zero-telemetry architecture: no analytics beacons, no tracking SDKs (Google Analytics, Firebase, Mixpanel, Sentry), and no crash reporters."}, {"topic": "local_sqlite_storage", "fact": "All user data (custom playlists, liked tracks, listening history, download metadata) is stored locally in an SQLite3 database in '~/Library/Application Support/Mooziac/'."}, {"topic": "security_entitlements", "fact": "Mooziac runs under macOS Hardened Runtime with JIT enabled for WebKit, outbound network access, and audio output enabled, while explicitly disabling audio input (microphone access)."}, {"topic": "power_management_sleep", "fact": "Mooziac creates an IOPMAssertion ('PreventUserIdleSystemSleep') and begins a ProcessInfo user-initiated activity so music playback continues uninterrupted when the display sleeps while the laptop lid is open."}, {"topic": "power_management_lid_close", "fact": "When the MacBook lid is closed or the Mac enters system sleep, Mooziac automatically pauses playback and enforces a paused state upon waking."}, {"topic": "performance_idle_cpu", "fact": "When playback is paused, Mooziac allows WebKit rendering engines to enter low-power sleep, keeping idle CPU usage below 0.4%."}, {"topic": "planned_feature_global_hotkeys_gui", "fact": "Customizable global keyboard shortcut configuration via a preferences UI is an open feature request (GitHub Issue #2) and is not yet implemented in v1.1.8."}, {"topic": "planned_feature_playlist_export", "fact": "Exporting and importing local playlists as .m3u, .m3u8, or .json files is an open feature request (GitHub Issue #3) and is not yet part of the v1.1.8 release."}, {"topic": "planned_feature_accent_color_picker", "fact": "A custom accent color picker for OLED Dark Mode is an open feature request (GitHub Issue #4) and is not currently available."}, {"topic": "building_prerequisites", "fact": "Building Mooziac from source requires macOS 13.0 or later, Xcode 15+ (or Command Line Tools), and Swift 5.9+ toolchain."}, {"topic": "building_commands", "fact": "To build and package Mooziac locally, clone the repo and run './build_app.sh' for debug launch or './build_app.sh --release-only' for universal release binaries and DMG."}, {"topic": "developer_logging", "fact": "Mooziac uses Apple Unified Logging (os.Logger) under subsystem 'app.mooziac.mac' with categories General, Playback, Sync, Download, Database, and Web."}, {"topic": "support_portal", "fact": "The official Mooziac support portal is hosted at https://mooziac.threeten.site/support.html, accessible directly from the menu bar context menu under 'Help & Support'."}], "troubleshooting": [{"problem": "macOS says 'Mooziac is damaged and can't be opened. You should move it to the Trash' or developer cannot be verified", "causes": ["Mooziac is distributed outside the Mac App Store and without an Apple Developer ID paid notarization ticket.", "macOS Gatekeeper attaches the quarantine extended attribute (com.apple.quarantine) to downloaded archives.", "macOS Gatekeeper blocked execution upon first launch."], "solutions": ["Open Terminal and run: xattr -cr /Applications/Mooziac.app to remove the quarantine flag.", "Alternatively, right-click (or Control-click) Mooziac.app in Finder, select 'Open', and click 'Open' in the confirmation prompt.", "Go to macOS System Settings > Privacy & Security, scroll down to the Security section, and click 'Open Anyway' next to the Mooziac notification."], "keywords": ["installation", "gatekeeper", "first_launch", "macos", "says", "mooziac", "damaged", "cant", "opened.", "should", "move", "trash", "developer", "cannot", "verified"]}, {"problem": "Trackpad Edge Volume gesture is not responding or changing volume", "causes": ["Swiping outside the active trigger zone (must be within the rightmost 2.5mm / x >= 0.982 of the trackpad).", "Swiping started in the lower 70% of the trackpad (gesture requires starting in the top 30% / y >= 0.70).", "Vertical movement was less than the 3.0mm activation threshold (designed to prevent typing accidents).", "Using an external standard mouse or third-party trackpad that does not support Apple MultitouchSupport framework events.", "Edge Volume is toggled off in Mooziac Settings > Gestures."], "solutions": ["Place your finger on the extreme right edge of the MacBook trackpad in the top 30% region, then slide downward or upward smoothly.", "Ensure you travel more than 3mm vertically to pass the anti-accidental-trigger deadzone.", "Check Mooziac Settings > Gestures to confirm 'Enable Edge Volume' is switched ON.", "Verify you are using a built-in MacBook trackpad or Apple Magic Trackpad (standard USB/Bluetooth mice do not emit multitouch digitizer packets)."], "keywords": ["trackpad_volume", "gestures", "edge_volume_engine", "trackpad", "edge", "volume", "gesture", "responding", "changing", "volume"]}, {"problem": "Downloaded track does not appear in local library or Downloads tab", "causes": ["The download failed or was interrupted mid-stream by network disconnection.", "The standalone yt-dlp helper binary failed to download or execute in ~/Library/Application Support/Mooziac/bin/.", "The destination folder (~/Music/Mooziac/) has write permission restrictions or disk is full.", "LocalDatabaseManager has not completed indexing the newly saved audio file into cached_tracks."], "solutions": ["Open the Downloads tab in Mooziac and check if the track is flagged with a red failure badge; click Retry.", "Check if ~/Music/Mooziac/ contains the downloaded file (.m4a, .mp3, or .opus). If the file exists there, select 'Rescan Library' from the File menu.", "Verify your internet connection and ensure YouTube Music InnerTube did not rate-limit requests.", "Check ~/Library/Application Support/Mooziac/bin/yt-dlp exists and has executable permissions (chmod +x)."], "keywords": ["downloads", "offline_playback", "dependency_manager", "local_database", "downloaded", "track", "does", "appear", "local", "library", "downloads"]}, {"problem": "Lyrics not showing or displaying 'No lyrics available'", "causes": ["Track lacks an entry on LRCLib (both exact duration lookup and fuzzy title/artist search failed).", "YouTube Music InnerTube lyrics endpoint does not have synchronized or plain text lyrics for this track.", "Track title contains complex metadata strings (e.g. '(Official Music Video)', '[Remastered 2024]') that confuse the search query.", "For local tracks, no matching .lrc file exists beside the audio file or in ~/Music/Mooziac/.", "Network connection is offline or blocking api.lrclib.net."], "solutions": ["Check your internet connection to ensure LRCLib API is reachable.", "For local audio files, download or create an .lrc file with the identical base filename (e.g., 'SongTitle.lrc' next to 'SongTitle.flac') and Mooziac will pick it up instantly.", "If using YouTube Music, ensure the song title is clean; Mooziac automatically cleans common suffixes like '(Official Audio)', but very custom upload titles may not find matches.", "Click the Lyrics button or toggle Cmd+Shift+L to force a fresh lyrics lookup."], "keywords": ["lyrics", "synced_lyrics", "lrclib", "lrc_fallback", "lyrics", "showing", "displaying", "lyrics", "available"]}, {"problem": "Lyrics out of sync with audio playback", "causes": ["The LRCLib or local .lrc timestamp offset does not match this specific audio edit (e.g., album version vs video version intro silence).", "Audio stream buffering caused an initial playback timing discrepancy.", "The matched lyrics belong to an alternative live or extended acoustic release."], "solutions": ["Open the Centered Lyrics HUD and use the Lyrics Offset slider (or Cmd+[ and Cmd+]) to adjust timing in +/- 0.5s increments.", "For local files, open the .lrc file in a text editor and adjust the global [offset:+/-ms] tag.", "Clear cached lyrics for the track from ~/Library/Caches/Mooziac/Lyrics/ to allow Mooziac to re-fetch the best matching version."], "keywords": ["lyrics", "synced_lyrics", "lrc_parser", "lyrics", "sync", "with", "audio", "playback"]}, {"problem": "Discord Rich Presence does not update or shows nothing", "causes": ["The official Discord macOS desktop application is not running.", "Discord Rich Presence is disabled in Mooziac Settings > Integrations.", "All Discord native IPC domain sockets (/tmp/discord-ipc-0 through /tmp/discord-ipc-9) are occupied or unreadable.", "Mooziac is running in 'Private Listening' mode.", "Discord user has 'Share activity status with others' disabled in Discord User Settings > Activity Privacy."], "solutions": ["Launch the Discord desktop app before or while running Mooziac.", "Open Mooziac Settings (Cmd+,) > Integrations and ensure 'Discord Rich Presence' is toggled ON.", "In Discord Settings > Activity Privacy, ensure 'Display current activity as a status message' is enabled.", "Restart Discord and Mooziac to reconnect the local Unix domain socket /tmp/discord-ipc-0."], "keywords": ["discord", "discord_rpc", "integrations", "discord", "rich", "presence", "does", "update", "shows", "nothing"]}, {"problem": "Spacebar pauses music while typing in YouTube Music search box", "causes": ["Running Mooziac version v1.1.0 where global key interceptors caught the Space key before HTML web input elements could process it."], "solutions": ["Update Mooziac to version v1.1.7 or newer where KeyboardCommandHandler explicitly checks first-responder focus on WKWebView input elements.", "Click outside the search box or hit Enter to commit the search query before pressing Spacebar."], "keywords": ["keyboard_shortcuts", "youtube_music", "playback", "spacebar", "pauses", "music", "while", "typing", "youtube", "music", "search"]}, {"problem": "Scrolling on Menu Bar item does not change volume", "causes": ["Running an earlier version where continuous trackpad scroll events in StatusItemManager did not trigger step increments.", "Volume mode is set to an inactive audio route.", "Scrolling was too light to exceed the 6-point trackpad threshold."], "solutions": ["Update Mooziac to v1.1.7+ where scroll gesture handling was fully rewritten with discrete 6pt trackpad / mouse notch accumulation.", "Place cursor over the Mooziac menu bar icon and swipe up or down firmly.", "Verify in Settings > Audio whether App Volume or System Sound is selected."], "keywords": ["menu_bar_player", "volume", "status_item", "scrolling", "menu", "item", "does", "change", "volume"]}, {"problem": "Settings panel text or controls are washed out or unreadable in Adaptive theme on macOS 27 beta", "causes": ["macOS 27 beta introduces altered dynamic semantic appearance inheritance where adaptive ambient colors clashed with light vibrancy materials."], "solutions": ["Update Mooziac to v1.1.1+, which explicitly pins SettingsPanel to dark tone (.dark) regardless of host system beta quirks.", "Switch to OLED Dark Mode or Pure Crystal Glass Mode in Settings > Appearance as an immediate workaround."], "keywords": ["themes", "settings", "adaptive_mode", "oled_mode", "settings", "panel", "text", "controls", "washed", "unreadable", "adaptive", "theme", "macos", "beta"]}, {"problem": "YouTube Music page is blank, stuck loading, or showing network error", "causes": ["Internet connection is offline or unstable.", "WebKit local cache or cookies became corrupt.", "A corporate firewall, VPN, or DNS filter is blocking music.youtube.com.", "Google anti-bot check triggered on the embedded WebKit instance."], "solutions": ["Check internet connection and verify music.youtube.com opens in Safari.", "Reload the page in Mooziac by pressing Cmd+R.", "Clear Mooziac WebKit cache: Quit Mooziac, delete ~/Library/Caches/site.threeten.mooziac/, and relaunch.", "Disconnect any VPNs or proxies that might interfere with Google's media CDNs."], "keywords": ["youtube_music", "web_view", "network", "youtube", "music", "page", "blank,", "stuck", "loading,", "showing", "network", "error"]}, {"problem": "Google Sign-In blocked with 'Couldn't sign you in - This browser or app may not be secure'", "causes": ["Google blocks standard embedded WebKit/WKWebView web views from signing into Google accounts to prevent phishing.", "The custom User-Agent string was reset or overridden."], "solutions": ["Mooziac uses a modern desktop Safari User-Agent to comply with Google authentication requirements. Ensure you are on the latest version of Mooziac.", "If 2-factor authentication fails via embedded browser, log into Google in your primary Safari browser first to establish a trusted device session, then log in via Mooziac.", "Do not disable JavaScript or modify WebKit security settings."], "keywords": ["youtube_music", "ytm_login", "privacy", "google", "sign-in", "blocked", "with", "couldnt", "sign", "this", "browser", "secure"]}, {"problem": "Local audio file fails to play or skips immediately to the next track", "causes": ["The audio file is in an unsupported or DRM-encrypted format (e.g. WMA, FairPlay AAC .m4p).", "The file was moved, renamed, or deleted in Finder after being added to Mooziac.", "Corrupted audio stream header causing AVFoundation to throw an initialization error.", "File resides on an unmounted external drive or disconnected network share (SMB/NFS)."], "solutions": ["Ensure the audio file is one of the supported formats: FLAC, MP3, M4A, AAC, WAV, AIFF, AIF, OGG, or OPUS.", "Verify the file is still present at its original path in Finder and that external storage drives are mounted.", "Test playing the file in QuickTime Player or VLC to confirm the audio stream is not corrupted.", "Remove and re-add the track or folder in Mooziac's local library."], "keywords": ["local_audio", "playback", "audio_engine", "local", "audio", "file", "fails", "play", "skips", "immediately", "next", "track"]}, {"problem": "Audio automatically pauses unexpectedly during playback", "causes": ["AirPods, Bluetooth headphones, or external DAC disconnected, causing AudioRouteMonitor to trigger safety auto-pause.", "Another application requested exclusive CoreAudio output or system audio was muted.", "The Mac entered system sleep or display sleep.", "Track finished and Repeat mode was OFF and Queue was empty."], "solutions": ["Check your headphone Bluetooth connection or battery level.", "Press Spacebar or Play in Mooziac after reconnecting audio output devices.", "Verify queue has upcoming tracks and repeat mode is set as desired in the playback toolbar."], "keywords": ["playback", "audio_routing", "volume", "audio", "automatically", "pauses", "unexpectedly", "during", "playback"]}, {"problem": "Mooziac main window disappeared but audio keeps playing", "causes": ["The main window was closed using the red traffic light button (Mooziac continues playing in the menu bar).", "The app was launched or switched into 'Menu Bar Only Mode' (Hide Dock Icon).", "Window minimized to Dock or hidden via Cmd+H."], "solutions": ["Click the Mooziac icon in the macOS menu bar at the top of your screen to show controls or reopen the window.", "Click the Mooziac Dock icon (if visible) to bring the main window to the front.", "Press Cmd+1 or use the menu bar item 'Show Main Window'."], "keywords": ["menu_bar_player", "window_management", "mooziac", "main", "window", "disappeared", "audio", "keeps", "playing"]}, {"problem": "Loudness Normalization makes music sound too quiet or muffled", "causes": ["Loudness Normalization is actively targeting -14 LUFS, which attenuates modern hyper-compressed 'loudness war' masterings.", "App Volume slider is set lower than 100% inside Mooziac."], "solutions": ["Open Mooziac Settings > Audio and uncheck 'Loudness Normalization' to listen to the unattenuated raw audio stream.", "Check that Mooziac's internal volume slider is set to 100% and adjust your Mac's master volume instead."], "keywords": ["volume", "loudness_normalization", "loudness", "normalization", "makes", "music", "sound", "quiet", "muffled"]}, {"problem": "Corner tap gestures trigger accidentally while typing or moving the cursor", "causes": ["Resting palms or thumb touching within the bottom 15% corners (y <= 0.15) of the trackpad.", "Accidental multi-tap detection due to trackpad sensitivity."], "solutions": ["Go to Mooziac Settings > Gestures and disable 'Enable Corner Tap Triggers'.", "Alternatively, re-map corner tap triggers to 'None' or less disruptive actions.", "Maintain typing posture keeping palms off the extreme lower corners of the trackpad."], "keywords": ["corner_gestures", "trackpad_volume", "gestures", "corner", "gestures", "trigger", "accidentally", "while", "typing", "moving", "cursor"]}, {"problem": "Mooziac icon missing from macOS menu bar", "causes": ["The menu bar is crowded with too many status icons, and macOS hid Mooziac behind the MacBook notch.", "Menu bar item was disabled in Mooziac Settings."], "solutions": ["Close or hide unused third-party menu bar items to make space.", "Use menu bar utilities like Ice or Bartender to organize icons around the notch.", "Verify in Mooziac Settings > General that 'Show in Menu Bar' is enabled."], "keywords": ["menu_bar_player", "status_item", "mooziac", "icon", "missing", "from", "macos", "menu"]}, {"problem": "Centered Lyrics HUD covers active window content or full-screen video", "causes": ["CenteredMenuBarLyricsWindowController uses a floating borderless window level (.floating / .statusBar) so it remains visible above normal windows.", "Lyrics HUD was left visible during video playback."], "solutions": ["Press Cmd+Shift+L to immediately dismiss the lyrics HUD.", "Perform a 3-tap gesture in the bottom-left corner of the trackpad to toggle HUD visibility.", "In Mooziac Settings > Lyrics, set the HUD to auto-hide when Mooziac is not playing."], "keywords": ["lyrics", "dynamic_island", "centered_lyrics", "centered", "lyrics", "covers", "active", "window", "content", "full-screen", "video"]}, {"problem": "FLAC audio plays but local .lrc lyrics file in the same folder does not load", "causes": ["The .lrc file name does not match the FLAC file name exactly (case-sensitive check before extension).", "The .lrc file is encoded with ANSI / Windows-1252 / UTF-16 instead of standard UTF-8.", "The .lrc file is in a different folder than the audio file and not in ~/Music/Mooziac/."], "solutions": ["Ensure the .lrc file has the exact same base name as the audio file (e.g. 'Track01.flac' and 'Track01.lrc').", "Open the .lrc file in a text editor and re-save it with UTF-8 encoding.", "Keep the .lrc file in the same folder as the FLAC file, or place it in ~/Music/Mooziac/."], "keywords": ["lyrics", "synced_lyrics", "local_audio", "flac", "audio", "plays", "local", ".lrc", "lyrics", "file", "same", "folder", "does", "load"]}, {"problem": "High CPU usage or battery drain on older Intel MacBooks", "causes": ["Using the 'Waveform' progress bar style which renders continuous 32-bar reactive animations.", "Running multiple animated theme layers simultaneously on an integrated Intel Iris/HD GPU."], "solutions": ["Switch Progress Bar Style to 'Minimal Line' in Settings > Appearance.", "Switch Theme to 'OLED Dark Mode' or disable ambient glow effects.", "Update to latest Mooziac version which includes optimized AppKit drawing pipelines."], "keywords": ["hardware", "performance", "themes", "progress_bars", "high", "usage", "battery", "drain", "older", "intel", "macbooks"]}, {"problem": "Downloads fail immediately with 'Helper binary not found' or execution error", "causes": ["DependencyManager failed to download the yt-dlp binary due to a captive portal, firewall, or GitHub downtime.", "The downloaded binary at ~/Library/Application Support/Mooziac/bin/yt-dlp was corrupted or lacks executable permissions (+x)."], "solutions": ["Verify your internet connection can reach https://github.com.", "Open Terminal and run: chmod +x ~/Library/Application\\ Support/Mooziac/bin/yt-dlp", "Delete ~/Library/Application Support/Mooziac/bin/yt-dlp and restart Mooziac to trigger a clean auto-download."], "keywords": ["downloads", "dependency_manager", "downloads", "fail", "immediately", "with", "helper", "binary", "found", "execution", "error"]}, {"problem": "Listening history is not being saved or playlists are missing", "causes": ["'Save Listening History' is disabled in Mooziac Settings > Privacy.", "The SQLite database at ~/Library/Application Support/Mooziac/mooziac.sqlite is locked or file permissions are broken.", "The user opened Mooziac in Guest user or temporary directory."], "solutions": ["Open Mooziac Settings > Privacy and ensure 'Save Listening History' is enabled.", "Check permissions on ~/Library/Application Support/Mooziac/ and ensure your user account has read/write access.", "If the SQLite file is corrupted, backup existing files and delete ~/Library/Application Support/Mooziac/mooziac.sqlite; Mooziac will recreate a clean database schema on next launch."], "keywords": ["privacy", "local_database", "listening_history", "playlists", "listening", "history", "being", "saved", "playlists", "missing"]}, {"problem": "Audio sounds distorted, crackly, or clipping at high volume", "causes": ["Both Mooziac App Volume and macOS System Sound are pushed beyond 0 dB using third-party sound boosters (e.g. Boom 3D, SoundSource).", "An audio driver sample rate mismatch between CoreAudio and a USB DAC."], "solutions": ["Enable 'Loudness Normalization' in Mooziac Settings > Audio to clamp peak audio levels to -14 LUFS.", "Disable software gain boosters or pre-amps in third-party audio utility apps.", "Open macOS Audio MIDI Setup (in Utilities) and ensure your output device sample rate is set to 44.1 kHz or 48.0 kHz."], "keywords": ["volume", "audio_engine", "loudness_normalization", "audio", "sounds", "distorted,", "crackly,", "clipping", "high", "volume"]}, {"problem": "Mooziac crashes on launch with an OS incompatibility message", "causes": ["Running macOS 12 Monterey, macOS 11 Big Sur, or older. Mooziac requires macOS 13.0 Ventura or later due to modern AppKit, Swift Concurrency, and WebKit APIs."], "solutions": ["Upgrade your Mac to macOS 13 Ventura, macOS 14 Sonoma, or macOS 15 Sequoia.", "Check macOS version in Apple menu () > About This Mac."], "keywords": ["hardware", "installation", "macos_compatibility", "mooziac", "crashes", "launch", "with", "incompatibility", "message"]}, {"problem": "Global Hotkey shortcuts (Cmd+Option+Space) do not trigger when Mooziac is in the background", "causes": ["Another running application (like Alfred, Raycast, or Zoom) has registered the identical global key combination.", "Input Monitoring or Accessibility permissions were revoked in macOS System Settings."], "solutions": ["Check for hotkey conflicts in other running utilities.", "Ensure Mooziac has necessary permissions in macOS System Settings > Privacy & Security > Accessibility if prompted.", "Use the menu bar item or trackpad corner tap gestures to control playback without conflicting with global keyboard hooks."], "keywords": ["keyboard_shortcuts", "global_hotkeys", "global", "hotkey", "shortcuts", "(cmd+option+space)", "trigger", "when", "mooziac", "background"]}], "faqs": [{"q": "What is Mooziac?", "a": "Mooziac is a native macOS music player written purely in Swift and AppKit. It unifies YouTube Music streaming with high-fidelity local audio playback (FLAC, MP3, WAV, etc.), featuring an innovative trackpad edge volume gesture, synchronized lyrics HUD docked beneath the MacBook notch, Discord Rich Presence, and customizable themes—all with zero telemetry and a tiny 40-90MB memory footprint.", "variations": ["what even is mooziac", "tell me about mooziac", "what does this app do", "is mooziac just a youtube music player?", "what's the point of mooziac"], "topics": ["what_is_mooziac", "local_audio", "youtube_music", "performance"]}, {"q": "Is Mooziac free and open source?", "a": "Yes. Mooziac is 100% free and open-source software licensed under the MIT License. There are no subscriptions, paywalls, or in-app purchases.", "variations": ["is mooziac free", "do i have to pay for this app", "is there a monthly subscription", "is mooziac open source", "how much does mooziac cost"], "topics": ["what_is_mooziac", "licensing"]}, {"q": "Why is Mooziac not available on the Mac App Store?", "a": "Mooziac uses low-level native macOS frameworks—specifically private MultitouchSupport dynamic linking for trackpad edge gestures and direct Unix domain sockets for Discord Rich Presence—which exceed Apple App Store sandbox constraints. Mooziac is distributed directly via GitHub releases as a DMG disk image.", "variations": ["why can't i find mooziac on the app store", "is mooziac in mac app store", "can i download this from apple app store", "why isn't this sandboxed in the store"], "topics": ["installation", "gatekeeper", "trackpad_volume"]}, {"q": "How do I install Mooziac on macOS?", "a": "Download the latest Mooziac.dmg disk image from the official GitHub releases page (https://github.com/shirkeharsh/mooziac/releases). Open the DMG file, drag the Mooziac icon into your Applications folder, and eject the disk image.", "variations": ["how to install mooziac", "how do i put mooziac on my mac", "where do i download the app", "how to get mooziac running"], "topics": ["installation", "first_launch"]}, {"q": "Why does macOS say 'Mooziac is damaged and can't be opened' or 'developer cannot be verified'?", "a": "Because Mooziac is an independent open-source project distributed without Apple Developer ID paid notarization, macOS Gatekeeper flags it with a quarantine attribute. To launch it: either right-click (Control-click) Mooziac in Finder and choose 'Open', approve it in macOS System Settings > Privacy & Security > 'Open Anyway', or run 'xattr -cr /Applications/Mooziac.app' in Terminal.", "variations": ["why does macos say it can't verify the developer", "mooziac is damaged and can't be opened", "mac won't let me open the app", "unidentified developer error", "how to bypass gatekeeper for mooziac"], "topics": ["installation", "gatekeeper", "troubleshooting"]}, {"q": "How do I completely uninstall Mooziac and remove all data?", "a": "Drag Mooziac.app from /Applications to the Trash. To completely remove all user data, database records, and downloaded caches, delete: ~/Library/Application Support/Mooziac/, ~/Library/Caches/Mooziac/, and ~/Library/Preferences/site.threeten.mooziac.plist. Your downloaded audio tracks in ~/Music/Mooziac/ will remain unless you delete that folder as well.", "variations": ["how do i uninstall it", "how to get rid of mooziac completely", "delete mooziac and all files", "how to remove mooziac from mac"], "topics": ["uninstalling", "privacy", "local_database"]}, {"q": "How does updating work in Mooziac?", "a": "Mooziac automatically checks the GitHub releases API on launch. If a new version is detected, an update banner appears with release notes and a direct download link. You can also manually check by selecting 'Check for Updates…' from the Mooziac application menu.", "variations": ["how to update mooziac", "does mooziac update automatically", "where do i get updates", "how do i check for new version"], "topics": ["updating", "software_update_manager"]}, {"q": "What audio formats does Mooziac support for local playback?", "a": "Mooziac natively supports FLAC, MP3, WAV, AAC, M4A, AIFF, AIF, OGG, and OPUS audio files using AVFoundation and CoreAudio pipelines.", "variations": ["what formats does it take", "does this support flac files?", "can i play mp3 and wav", "does mooziac play ogg and opus", "audio codecs supported"], "topics": ["local_audio", "playback"]}, {"q": "How do I add my own local music library to Mooziac?", "a": "Select 'Add Music Folder…' from the File menu (or press Cmd+O) and select any folder containing your audio files. Mooziac scans the directory recursively in the background, extracts embedded ID3/Vorbis metadata, and indexes the tracks into your local library SQLite database.", "variations": ["can i use my own music", "how to import local songs", "how do i add mp3s from my mac", "load local library", "can i play local files in mooziac"], "topics": ["local_audio", "local_library_database"]}, {"q": "Can I use Mooziac without an internet connection?", "a": "Yes. Mooziac functions as a fully offline local audio player for all files stored on your disk or downloaded from YouTube Music. When offline, local audio playback, queue management, and local .lrc lyrics work without needing any network access.", "variations": ["can i use this without internet", "can i listen offline", "does mooziac work offline", "offline mode playback"], "topics": ["offline_playback", "local_audio", "downloads"]}, {"q": "Where are downloaded songs stored on my Mac?", "a": "By default, Mooziac saves all downloaded tracks to ~/Music/Mooziac/ on your user home folder. You can change this destination anytime in Mooziac Settings > Downloads.", "variations": ["where did my downloaded song go", "where are my downloads stored", "it downloaded but i can't find it", "bro where did my music go", "download path for songs"], "topics": ["downloads", "offline_playback", "download_location"]}, {"q": "Do I need to install yt-dlp or Python to download songs?", "a": "No. Mooziac has an internal DependencyManager that automatically downloads the standalone macOS binary of yt-dlp into ~/Library/Application Support/Mooziac/bin/yt-dlp during your first download request. No external tools, Homebrew packages, or Python environments are required.", "variations": ["do i need python for downloading", "do i need to brew install yt-dlp", "how does mooziac download youtube songs", "yt-dlp setup for mooziac"], "topics": ["downloads", "dependency_manager"]}, {"q": "How does the Trackpad Edge Volume gesture work?", "a": "Place your finger on the extreme right 2.5mm edge (normalized x >= 0.982) in the top 30% of your built-in MacBook trackpad or Magic Trackpad, and slide smoothly down or up. Mooziac features a 3.0mm movement deadzone to avoid accidental triggers while typing, and 160mm total travel maps to 0-100% volume.", "variations": ["how do i make this louder", "why is my volume gesture not working", "why tf is the volume gesture not working", "how does trackpad edge volume work", "volume slide on trackpad"], "topics": ["trackpad_volume", "gestures", "edge_volume_engine"]}, {"q": "What are the trackpad corner tap gestures?", "a": "By default, multi-tapping in the bottom corners of your trackpad triggers playback controls: 2 taps in the bottom-right corner skips to Next Track, 3 taps skips to Previous Track; 2 taps in the bottom-left corner toggles Play/Pause, and 3 taps toggles the Centered Lyrics HUD. Corner triggers can be remapped to 16 actions or disabled in Settings > Gestures.", "variations": ["what do the corner taps do", "trackpad corner controls", "how to skip tracks with trackpad", "tap corner to pause music", "configure trackpad corners"], "topics": ["corner_gestures", "gestures", "edge_volume_engine"]}, {"q": "What is the difference between 'System Sound' and 'Focus Audio' volume modes?", "a": "'System Sound' directly adjusts your Mac's CoreAudio master output volume, identical to the macOS volume keys. 'Focus Audio' (or Separate App Sound) adjusts Mooziac's internal playback volume independently, leaving your Mac's master volume and other applications (like Discord or games) untouched.", "variations": ["what is focus audio volume", "difference between system sound and focus audio", "can i change mooziac volume without changing mac volume", "separate app volume control"], "topics": ["volume", "dual_volume_modes"]}, {"q": "Does Mooziac support loudness normalization?", "a": "Yes. Mooziac includes an integrated Loudness Normalizer calibrated to the industry-standard -14 LUFS target. It applies smooth 250ms cosine volume easing transitions between tracks to avoid abrupt volume spikes or ear fatigue.", "variations": ["does mooziac normalize volume", "stop songs from blasting my ears", "volume level matching across songs", "what is -14 LUFS in mooziac"], "topics": ["volume", "loudness_normalization"]}, {"q": "How does Mooziac find and display synchronized lyrics?", "a": "Mooziac uses a multi-tier fallback pipeline: first it checks for local .lrc files in the audio folder and ~/Music/Mooziac/; then it checks local disk cache; next it queries the YouTube Music InnerTube synced lyrics endpoint; then it queries the LRCLib API (exact lookup followed by fuzzy title/artist searches); and finally falls back to plain text lyrics. Synced lyrics scroll automatically line-by-line.", "variations": ["yo why aren't my lyrics showing", "lyrics don't work for me", "where does mooziac get lyrics", "how to get synced lyrics", "how does the lyrics feature work"], "topics": ["lyrics", "synced_lyrics", "lrclib", "lrc_fallback"]}, {"q": "What is the Centered Menu Bar / Notch Lyrics HUD?", "a": "The Centered Lyrics HUD is a floating borderless pill window docked directly beneath the MacBook camera notch (or centered along the top menu bar on notch-less displays). It shows the current line of synchronized lyrics and playback state. You can toggle it via Cmd+Shift+L or a 3-tap gesture in the bottom-left corner of the trackpad.", "variations": ["can i put lyrics under the notch", "dynamic island player for mac", "lyrics floating window under menu bar", "how to show the notch lyrics hud"], "topics": ["lyrics", "dynamic_island", "centered_lyrics_hud"]}, {"q": "How do I show what I'm listening to on Discord?", "a": "Enable 'Discord Rich Presence' in Mooziac Settings > Integrations and ensure the Discord desktop application is open. Mooziac connects directly to the local Discord client via native Unix domain sockets (/tmp/discord-ipc-0) to broadcast the track title, artist, album art, and live elapsed time with zero external background processes.", "variations": ["why is discord not showing what i'm listening to", "how to get discord status for mooziac", "discord rich presence not working", "discord rpc setup mooziac"], "topics": ["discord", "discord_rich_presence"]}, {"q": "What themes are available in Mooziac?", "a": "Mooziac offers four built-in themes in Settings > Appearance: Adaptive (ambient dynamic glow extracted from album artwork), OLED Dark Mode (true #000000 deep black with high-contrast accents), Pure Crystal Glass (translucent glass with a 1.2px rim stroke), and Watery Pure Transparent (seamless macOS desktop wallpaper vibrancy).", "variations": ["what themes does mooziac have", "how to enable oled dark mode", "does mooziac have dynamic ambient lighting", "change app appearance"], "topics": ["themes", "oled_mode", "adaptive_mode"]}, {"q": "What progress bar styles can I choose from?", "a": "Under Settings > Appearance, you can select from four progress bar styles: Waveform (32-bar animated reactive audio wave), Neon Glow (liquid glowing capsule scrubber), Cyber Dots (retro pulsing LED matrix), and Minimal Line (clean, zero-CPU precision line).", "variations": ["how to change the seek bar style", "can i make the scrubber look like a sound wave", "different progress bar animations", "neon progress bar option"], "topics": ["progress_bars", "appearance"]}, {"q": "How do I control Mooziac from the macOS Menu Bar?", "a": "Mooziac displays an icon in your macOS status menu bar. You can scroll directly over the icon with your trackpad or mouse to change volume, click it to reveal playback controls and track information, or enable 'Menu Bar Only Mode' in Settings to hide the Dock icon completely.", "variations": ["how do i get this thing out of the menu bar", "can mooziac run only in the menu bar", "control music from top bar", "menu bar scrolling volume"], "topics": ["menu_bar_player", "menu_bar_volume_scroll"]}, {"q": "Does Mooziac track my listening habits or collect analytics?", "a": "No. Mooziac is designed with absolute user privacy in mind. It contains zero analytics SDKs, zero telemetry collectors, and zero third-party tracking cookies. Your listening history, favorites, and playlists are stored exclusively on your local disk in an SQLite database.", "variations": ["does mooziac collect data", "is mooziac safe and private", "does mooziac send telemetry to servers", "what data does mooziac store"], "topics": ["privacy", "local_database"]}, {"q": "Does Mooziac support both Apple Silicon and Intel Macs?", "a": "Yes. Mooziac is compiled as a Universal 2 macOS application containing native binary slices for both Apple Silicon (arm64: M1, M2, M3, M4) and Intel (x86_64) processors. It runs natively on both architectures without requiring Rosetta 2.", "variations": ["does this work on an intel mac", "is mooziac native for m1 m2 m3 mac", "universal binary support", "intel vs apple silicon performance"], "topics": ["hardware", "macos_compatibility"]}, {"q": "What macOS versions are supported by Mooziac?", "a": "Mooziac requires macOS 13.0 (Ventura) or newer, including macOS 14 Sonoma and macOS 15 Sequoia. It does not support macOS 12 Monterey or earlier due to modern Swift Concurrency and AppKit dependencies.", "variations": ["what macos do i need for mooziac", "does mooziac work on ventura sonoma sequoia", "can i run mooziac on macos monterey", "minimum system requirements"], "topics": ["hardware", "macos_compatibility"]}, {"q": "How does Mooziac's memory and CPU usage compare to Spotify or web apps?", "a": "Because Mooziac is written purely in native Swift/AppKit without heavy Electron or Chromium application wrappers, local audio playback typically uses only 40MB to 90MB of RAM and under 1.5% CPU. Even during YouTube Music streaming, WebKit consumption averages 120MB to 180MB, compared to 400MB to 800MB+ for Electron apps.", "variations": ["how much ram does mooziac use", "is mooziac lighter than spotify", "does mooziac waste battery", "native swift vs electron performance"], "topics": ["hardware", "performance"]}, {"q": "What keyboard shortcuts are available in Mooziac?", "a": "Key shortcuts include: Space (Play/Pause), Left/Right Arrows (Seek +/- 5s, Shift for 15s), Cmd+L (Show lyrics tab), Cmd+Shift+L (Toggle floating Notch Lyrics HUD), Cmd+S (Shuffle queue), Cmd+R (Toggle repeat mode), Cmd+M (Mute), Cmd+, (Settings), and Cmd+Q (Quit). Global hotkeys (Cmd+Opt+Space) work even when Mooziac is in the background.", "variations": ["what are the shortcuts for mooziac", "hotkeys to control playback", "how to skip with keyboard", "global hotkey shortcuts"], "topics": ["keyboard_shortcuts", "global_hotkeys"]}, {"q": "How do I manage and reorder songs in the playback queue?", "a": "Open the Queue drawer by clicking the queue icon on the bottom playback bar. You can drag and drop tracks to change play order, select tracks and press Delete to remove them, or click 'Clear Queue' to wipe all upcoming songs.", "variations": ["how to reorder queue", "can i drag and drop songs in queue", "how do i clear the up next list", "queue controls in mooziac"], "topics": ["queue", "playback"]}, {"q": "How do I log into my YouTube Music account?", "a": "Click the YouTube Music tab in Mooziac and click 'Sign In' in the top-right corner of the YouTube Music interface. Sign into your Google account as you normally would. Mooziac utilizes an authentic Safari desktop User-Agent to ensure standard Google authentication without security blocks.", "variations": ["how to log in to youtube music", "can i access my liked songs from youtube", "google sign in on mooziac", "ytm login steps"], "topics": ["youtube_music", "ytm_login"]}, {"q": "Can I import playlists into Mooziac?", "a": "When logged into YouTube Music, all of your existing YouTube Music playlists, Liked Songs, and saved albums appear automatically in Mooziac. For local audio, you can organize tracks into folders and import the entire directory into your Mooziac library.", "variations": ["can i import my playlist", "how to sync my spotify or youtube playlists", "bring my playlists to mooziac", "importing songs from itunes"], "topics": ["playlists", "youtube_music", "local_audio"]}, {"q": "Can I export my Mooziac playlists to .m3u8 or .json files?", "a": "Not currently. Playlists created locally are stored in the local SQLite database (~/Library/Application Support/Mooziac/mooziac.sqlite). Direct export to .m3u8 or .json playlist files is an open feature request on GitHub (Issue #3) and planned for a future update.", "variations": ["can i export my playlist to m3u", "how to export playlists from mooziac", "save playlist as file", "m3u8 export support"], "topics": ["playlists", "planned_features"]}, {"q": "Does Mooziac have an equalizer (EQ) or bass booster?", "a": "Mooziac does not currently have a built-in graphic equalizer or bass booster. Audio is rendered bit-perfect with optional -14 LUFS loudness normalization. A 10-band graphic equalizer is a widely requested feature currently under consideration.", "variations": ["is there an equalizer in mooziac", "how to turn up bass", "graphic eq with presets", "does mooziac have eq"], "topics": ["audio", "requested_features", "volume"]}, {"q": "How do I report a bug or unexpected behavior in Mooziac?", "a": "Report issues on the official GitHub repository at https://github.com/shirkeharsh/mooziac/issues. Include your macOS version, Mac hardware model (Intel or Apple Silicon), Mooziac version, and detailed steps to reproduce the problem. You can also submit feedback via the web portal at https://mooziac.threeten.site/support.html.", "variations": ["how do i report a bug", "where to submit error logs", "it just stopped working how do i fix this", "my song isn't playing bug report", "contact mooziac support"], "topics": ["reporting_bugs", "troubleshooting"]}, {"q": "How do I suggest a new feature or enhancement for Mooziac?", "a": "Submit a feature proposal on GitHub under Issues or Discussions (https://github.com/shirkeharsh/mooziac/issues). Check existing issues first to see if your feature (such as customizable hotkeys or playlist export) has already been requested, and add your feedback there.", "variations": ["how to request a feature", "can you add this feature to mooziac", "feature suggestions for mooziac", "submit an idea"], "topics": ["requesting_features"]}, {"q": "How do I build Mooziac from source code?", "a": "Clone the repository from GitHub: 'git clone https://github.com/shirkeharsh/mooziac.git'. Ensure you have Xcode 15+ and Swift 5.9+ installed on macOS 13+. Run './build_app.sh' in Terminal to build the Universal 2 binary and assemble the complete Mooziac.app bundle inside dist/.", "variations": ["how to build mooziac from source", "compile mooziac with xcode", "build_app.sh instructions", "developer build setup"], "topics": ["building", "development"]}], "limitations": [{"topic": "windows_linux", "keywords": ["windows", "linux", "pc", "android", "ios", "iphone", "operating system", "os"], "message": "Mooziac is exclusively built for macOS (macOS 13.0 Ventura, Sonoma, and Sequoia). It does not support Windows, Linux, Android, or iOS because it relies natively on macOS AppKit, AVFoundation, CoreAudio, and Apple MultitouchSupport frameworks."}, {"topic": "equalizer", "keywords": ["equalizer", "eq", "bass", "treble", "bass boost", "graphic eq"], "message": "Mooziac currently renders audio flat and bit-perfect with -14 LUFS loudness normalization. It does not currently feature a built-in 10-band graphic equalizer or bass booster slider. If you need system-wide EQ on macOS, third-party utilities like eqMac or SoundSource work seamlessly alongside Mooziac."}, {"topic": "spotify_apple_music", "keywords": ["spotify", "apple music", "tidal", "deezer", "qobuz"], "message": "Mooziac streams exclusively from YouTube Music and plays high-fidelity local audio files (FLAC, MP3, WAV, etc.). It does not support streaming directly from Spotify, Apple Music, or Tidal."}, {"topic": "tag_editor", "keywords": ["tag editor", "edit tags", "id3", "change artist", "rename track", "album art edit"], "message": "Mooziac reads metadata (ID3, Vorbis, MP4) from audio files to index your library, but it does not include an in-app tag editor. To edit audio tags or embed artwork, we recommend free external tools like Kid3 or MusicBrainz Picard."}]};

const STOP_WORDS = new Set([
  'the', 'is', 'at', 'which', 'on', 'a', 'an', 'and', 'or', 'but', 'if', 'then',
  'else', 'when', 'up', 'down', 'in', 'out', 'to', 'for', 'of', 'with', 'about',
  'against', 'between', 'into', 'through', 'during', 'before', 'after', 'above',
  'below', 'from', 'can', 'cant', 'cannot', 'could', 'should', 'would', 'does',
  'doesnt', 'did', 'didnt', 'doing', 'have', 'has', 'had', 'having', 'do', 'how',
  'what', 'why', 'where', 'who', 'this', 'that', 'these', 'those', 'i', 'my', 'me',
  'you', 'your', 'it', 'its', 'app', 'song', 'music', 'work', 'make', 'just', 'get'
]);

function tokenize(text) {
  if (!text) return [];
  return text.toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 2 && !STOP_WORDS.has(w));
}

function scoreMatch(queryWords, fullText, keywords = []) {
  let score = 0;
  const lowerText = fullText.toLowerCase();

  for (const word of queryWords) {
    // Word boundary or inclusion match
    if (lowerText.includes(word)) {
      score += 3;
    }
    for (const kw of keywords) {
      const lowerKw = kw.toLowerCase();
      if (lowerKw === word) {
        score += 8;
      } else if (lowerKw.includes(word) || word.includes(lowerKw)) {
        score += 4;
      }
    }
  }
  return score;
}

function retrieveContext(userQuery) {
  const lowerQuery = userQuery.toLowerCase();
  const words = tokenize(userQuery);
  const scoredItems = [];

  // Check specific hard limitations first
  for (const lim of KB.limitations) {
    for (const kw of lim.keywords) {
      const reg = new RegExp('\\b' + kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i');
      if (reg.test(lowerQuery)) {
        scoredItems.push({
          type: 'limitation',
          score: 50,
          title: lim.topic,
          text: lim.message
        });
        break;
      }
    }
  }

  // Score FAQs
  for (const f of KB.faqs) {
    // Check direct variation match
    const directVar = f.variations.some(v => lowerQuery.includes(v.toLowerCase()) || v.toLowerCase().includes(lowerQuery));
    let baseScore = directVar ? 30 : 0;
    
    const s = scoreMatch(words, f.q + ' ' + f.variations.join(' ') + ' ' + f.a, f.topics);
    if (s + baseScore > 0) {
      scoredItems.push({
        type: 'faq',
        score: s + baseScore,
        title: f.q,
        text: `Q: ${f.q}\nA: ${f.a}`
      });
    }
  }

  // Score troubleshooting
  for (const t of KB.troubleshooting) {
    const s = scoreMatch(words, t.problem + ' ' + t.solutions.join(' '), t.keywords);
    if (s > 0) {
      scoredItems.push({
        type: 'troubleshooting',
        score: s,
        title: t.problem,
        text: `Problem: ${t.problem}\nSolutions:\n${t.solutions.map(sol => '- ' + sol).join('\n')}`
      });
    }
  }

  // Score facts
  for (const f of KB.facts) {
    const s = scoreMatch(words, f.fact, [f.topic]);
    if (s > 0) {
      scoredItems.push({
        type: 'fact',
        score: s,
        title: f.topic,
        text: `- ${f.fact}`
      });
    }
  }

  scoredItems.sort((a, b) => b.score - a.score);
  return scoredItems.slice(0, 5);
}

function generateDeterministicAnswer(userQuery, topMatches) {
  if (!topMatches || topMatches.length === 0) {
    return "I couldn't find a direct answer to that specific question in the Mooziac documentation.\n\nHere are some common topics I can help with:\n• **Trackpad Gestures:** Edge volume sliding & corner taps\n• **Installation:** Gatekeeper quarantine (`xattr -cr`)\n• **Lyrics:** Notch HUD & Synced LRC files\n• **Downloads:** Offline playback in `~/Music/Mooziac/`\n• **Audio:** FLAC, bit-perfect sound & -14 LUFS normalizer\n\nOr submit an issue on [GitHub](https://github.com/shirkeharsh/mooziac/issues)!";
  }

  const best = topMatches[0];
  if (best.type === 'limitation') {
    return best.text;
  } else if (best.type === 'troubleshooting') {
    return `### ${best.title}\n\n${best.text.replace('Problem: ' + best.title + '\n', '')}\n\n*Source: Mooziac Troubleshooting Guide*`;
  } else if (best.type === 'faq') {
    return `${best.text.replace(/Q: .*?\nA: /, '')}\n\n*Source: Mooziac Documentation*`;
  } else {
    const factsList = topMatches.map(m => m.text).join('\n');
    return `Here is what the Mooziac documentation says regarding your question:\n\n${factsList}\n\nNeed more help? Check out [GitHub Issues](https://github.com/shirkeharsh/mooziac/issues).`;
  }
}

// In-memory sliding window rate limiter per edge isolate
const chatRateLimitMap = new Map();

function checkChatRateLimit(ip) {
  const now = Date.now();
  const windowMs = 60 * 1000; // 1 minute
  const maxPerMin = 6;
  const longWindowMs = 10 * 60 * 1000; // 10 minutes
  const maxPer10Min = 25;

  let timestamps = chatRateLimitMap.get(ip) || [];
  timestamps = timestamps.filter(t => now - t < longWindowMs);

  const countLastMin = timestamps.filter(t => now - t < windowMs).length;
  if (countLastMin >= maxPerMin) {
    return { limited: true, error: "You're sending questions too quickly. Please wait a minute." };
  }
  if (timestamps.length >= maxPer10Min) {
    return { limited: true, error: "Session rate limit reached. Please wait a few minutes before asking more questions." };
  }

  timestamps.push(now);
  chatRateLimitMap.set(ip, timestamps);

  if (chatRateLimitMap.size > 2000) {
    for (const [k, v] of chatRateLimitMap.entries()) {
      if (v.every(t => now - t > longWindowMs)) chatRateLimitMap.delete(k);
    }
  }

  return { limited: false };
}

// Moderation Patterns: Profanity, NSFW, Harassment, Jailbreaks, Spam
const NSFW_AND_ABUSE_REGEX = /\b(nude|nudes|porn|pornography|nsfw|hentai|erotic|sex|sexy|boobs|penis|vagina|dildo|orgasm|cum|blowjob|fuck|fucking|fucker|shit|bitch|asshole|bastard|cunt|dick|pussy|faggot|nigger|retard|kill\s+yourself|die\s+in\s+a\s+fire|casino|poker|viagra|free\s+crypto|telegram\s+channel)\b/i;

const PROMPT_INJECTION_REGEX = /(ignore\s+(all\s+)?(previous|prior|above)\s+instructions|reveal\s+(your\s+)?(system\s+prompt|instructions|secret)|you\s+are\s+now\s+(DAN|unrestricted|in\s+developer\s+mode)|bypass\s+(all\s+)?(safety|filters))/i;

export async function onRequestPost(context) {
  const { request, env } = context;

  const corsHeaders = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Content-Type': 'application/json'
  };

  try {
    const clientIp = request.headers.get('cf-connecting-ip') || request.headers.get('x-real-ip') || 'unknown';

    // 1. Rate Limiting Check
    const rateCheck = checkChatRateLimit(clientIp);
    if (rateCheck.limited) {
      return new Response(JSON.stringify({
        reply: `⏳ ${rateCheck.error}`,
        source: 'rate_limiter',
        model: 'edge_guardrail'
      }), {
        status: 429,
        headers: {
          ...corsHeaders,
          'Retry-After': '60'
        }
      });
    }

    const body = await request.json().catch(() => ({}));

    // 2. Honeypot Bot Trap: Drop automated bots instantly without wasting AI tokens
    if (body.website || body.mzc_hp || body.url_ref) {
      return new Response(JSON.stringify({
        reply: "Thanks for reaching out!",
        source: "bot_trap",
        model: "edge_guardrail"
      }), { status: 200, headers: corsHeaders });
    }

    const userQuery = (body.message || body.query || '').trim();

    // 3. Message Length & Spam Flood Validation
    if (!userQuery || userQuery.length < 2) {
      return new Response(JSON.stringify({ error: "Please enter a valid question." }), {
        status: 400,
        headers: corsHeaders
      });
    }

    if (userQuery.length > 500) {
      return new Response(JSON.stringify({
        reply: "Your question is too long (over 500 characters). Please summarize your question so I can assist you better.",
        source: "guardrail_length",
        model: "edge_guardrail"
      }), { status: 200, headers: corsHeaders });
    }

    if (/(.)\1{12,}/i.test(userQuery)) {
      return new Response(JSON.stringify({
        reply: "Please ask a clear, constructive question about Mooziac.",
        source: "guardrail_spam",
        model: "edge_guardrail"
      }), { status: 200, headers: corsHeaders });
    }

    const words = userQuery.toLowerCase().split(/\s+/).filter(Boolean);
    if (words.length >= 8 && new Set(words).size <= 2) {
      return new Response(JSON.stringify({
        reply: "Please ask a constructive question without repeating the same words.",
        source: "guardrail_spam",
        model: "edge_guardrail"
      }), { status: 200, headers: corsHeaders });
    }

    // 4. Content Moderation: Reject NSFW, Profanity, Abuse & Jailbreaks before calling AI
    if (NSFW_AND_ABUSE_REGEX.test(userQuery) || PROMPT_INJECTION_REGEX.test(userQuery)) {
      return new Response(JSON.stringify({
        reply: "I am the Mooziac Support AI and can only assist with questions regarding the Mooziac macOS music player, troubleshooting, and features. Please keep messages respectful and relevant to Mooziac.",
        source: "content_moderation_guardrail",
        model: "edge_guardrail"
      }), {
        status: 200,
        headers: corsHeaders
      });
    }

    // 5. Retrieve top facts
    const relevantItems = retrieveContext(userQuery);
    const contextText = relevantItems.map(item => item.text).join('\n\n');

    // 6. Check if Cloudflare Workers AI is available in env
    if (env && env.AI) {
      try {
        const systemPrompt = `You are the official Mooziac Support AI for Mooziac (https://mooziac.threeten.site), a native macOS music player.
You must answer concisely, accurately, and politely in Markdown.

CRITICAL TECHNICAL RULES:
- ONLY answer using the provided Mooziac context.
- If a feature does NOT exist (e.g. 10-band equalizer, Windows/Linux support, Spotify streaming, ID3 tag editing), explicitly state that it is not supported.
- If user asks why volume gesture does not work: explain it requires built-in or Magic Trackpad, starting in top 30% of trackpad, rightmost 2.5mm edge, and 3.0mm vertical movement deadzone.
- If user gets macOS Gatekeeper 'damaged' warning: provide 'xattr -cr /Applications/Mooziac.app' or System Settings > Privacy & Security > Open Anyway.
- If user asks where downloads are: explain default is ~/Music/Mooziac/.
- If user asks about lyrics: explain local .lrc, YouTube Music, LRCLib fallback, and the Centered Notch HUD (Cmd+Shift+L).

RELEVANT CONTEXT:
${contextText || "General Mooziac native macOS music player inquiry."}`;

        const messages = [
          { role: "system", content: systemPrompt }
        ];

        // Include recent conversation history if provided
        if (Array.isArray(body.history)) {
          for (const h of body.history.slice(-4)) {
            if (h.role && h.content) {
              messages.push({ role: h.role === 'user' ? 'user' : 'assistant', content: h.content });
            }
          }
        }

        messages.push({ role: "user", content: userQuery });

        // Run Cloudflare Workers AI (Llama 3.2 1B)
        const model = env.AI_MODEL || '@cf/meta/llama-3.2-1b-instruct';
        const aiResponse = await env.AI.run(model, {
          messages: messages,
          max_tokens: 512,
          temperature: 0.2
        });

        const reply = aiResponse.response || aiResponse.text || '';
        if (reply.trim()) {
          return new Response(JSON.stringify({
            reply: reply.trim(),
            source: 'cloudflare_workers_ai',
            model: model
          }), {
            status: 200,
            headers: corsHeaders
          });
        }
      } catch (aiError) {
        console.warn("Workers AI execution error, falling back to deterministic KB:", aiError);
      }
    }

    // 3. Fallback: Return verified deterministic answer from knowledge base
    const fallbackReply = generateDeterministicAnswer(userQuery, relevantItems);
    return new Response(JSON.stringify({
      reply: fallbackReply,
      source: 'mooziac_knowledge_base',
      model: 'deterministic_engine'
    }), {
      status: 200,
      headers: corsHeaders
    });

  } catch (err) {
    return new Response(JSON.stringify({
      error: "Internal server error",
      details: err.message
    }), {
      status: 500,
      headers: corsHeaders
    });
  }
}

export async function onRequestOptions() {
  return new Response(null, {
    status: 204,
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type',
      'Access-Control-Max-Age': '86400'
    }
  });
}
